import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes2')
from h import *
X=[]
X.append(r(9730903,"Sopa de frijoles en Instant Pot [chili vegano]","Disfrute de un chili vegano saludable y delicioso, sustancioso y lleno de sabor.","6 porciones","1 porción",
["1 cebolla amarilla picada","2 tallos de apio en rodajas finas","2 zanahorias grandes peladas y en rodajas","8 onzas de champiñones cremini cortados en cuartos","1 pimiento rojo picado (o del color de su elección)","2 latas de 15 onzas de frijoles negros, escurridos y enjuagados","1 lata de 15 onzas de frijoles rojos (kidney), escurridos y enjuagados","1 cucharada de pasta de miso blanco","2 tazas de salsa de tomate","2 tazas de caldo de verduras bajo en sodio","2 cucharadas de chile en polvo","1 cucharada de pimentón ahumado","1 cucharadita de ajo en polvo","1 cucharadita de cebolla en polvo","1 cucharadita de comino","sal + pimienta al gusto",("Coberturas + decoraciones opcionales","crema de nuez de la India (anacardo)"),("Coberturas + decoraciones opcionales","guacamole"),("Coberturas + decoraciones opcionales","aguacate, jalapeño, cilantro o perejil fresco")],
[("Instrucciones para Instant Pot","Agregue todos los ingredientes a su Instant Pot y revuelva para combinar. Luego cierre la tapa y coloque la válvula en la posición de sellado. Programe a alta presión y cocine a presión durante 3 minutos. (Tardará unos 20 minutos en acumular presión antes de comenzar la cuenta regresiva.) Luego libere la válvula rápidamente cuando termine el temporizador y retire la tapa cuando sea seguro hacerlo."),("Instrucciones para Instant Pot","Pruebe la sal y la pimienta de la sopa y agregue un poco si es necesario. Luego pase 2 tazas de la sopa cocida a una licuadora y procese hasta que quede suave. Vuelva a incorporarla a la olla. (O use una licuadora de inmersión para hacer puré UNA PARTE de la sopa y espesarla.)"),("Instrucciones para Instant Pot","Sirva con las coberturas de su elección."),("Instrucciones para la estufa","Agregue todos los ingredientes a una olla grande, más caldo o agua adicional si es necesario para cubrir apenas las verduras. Cocine a fuego lento a fuego medio-bajo de 25 a 30 minutos, o hasta que las zanahorias y el apio estén tiernos."),("Instrucciones para la estufa","Pruebe la sal y la pimienta de la sopa y agregue un poco si es necesario. Luego pase 2 tazas de la sopa cocida a una licuadora y procese hasta que quede suave. Devuélvala a la olla y mezcle bien. (O use una licuadora de inmersión para hacer puré UNA PARTE de la sopa y espesarla.)"),("Instrucciones para la estufa","Sirva con las coberturas de su elección.")],
["Use frijoles enlatados, a menos que planee precocinar frijoles secos. Los frijoles secos no se cocinarán lo suficiente en el corto tiempo de cocción que requiere esta receta rápida.","Para usar frijoles secos: No aumente el tiempo de cocción o las verduras se cocinarán de más. En su lugar, precocine los frijoles en la estufa O cocínelos primero a presión por separado.","Las sobras se conservan refrigeradas de 3 a 4 días o congeladas hasta por 3 meses."],[]))
X.append(r(9733821,"Sándwich rápido + sencillo de ensalada de garbanzos ¡sin mayonesa!","¡Un sándwich de ensalada de garbanzos con muchísimo sabor! Solo 10 minutos y 10 ingredientes para un almuerzo o cena rápidos y deliciosos.","3 sándwiches","1 porción",
[("Para la ensalada","1 lata de 15 onzas de garbanzos, escurridos y enjuagados"),("Para la ensalada","½ taza de apio picado en cubos (aprox. 1 tallo mediano)"),("Para la ensalada","½ taza de pimiento rojo o amarillo picado en cubos (aprox. la mitad de un pimiento mediano)"),("Para la ensalada","2 cucharadas de mostaza amarilla"),("Para la ensalada","2 cucharadas de tahini"),("Para la ensalada","2 cucharadas de arándanos rojos secos sin azúcar"),("Para la ensalada","2 cucharaditas de eneldo seco"),("Para la ensalada","1 cucharadita de ajo en polvo"),("Para la ensalada","¼ de cucharadita de sal marina o más al gusto"),("Para la ensalada","¼ de cucharadita de pimienta negra o más al gusto"),("Para servir","pan integral en rebanadas, sin gluten si lo prefiere"),("Para servir","rodajas de tomate, pepinillos, lechuga")],
["Coloque los garbanzos escurridos en un tazón para mezclar y use un tenedor o un machacador de papas para machacarlos suavemente. Deje algunos enteros, no los machaque demasiado; queremos algo de textura.","Agregue todos los demás ingredientes de la ensalada y mezcle bien.","Sirva sobre el pan en rebanadas de su elección (suave o tostado), con lechuga, tomate y pepinillos, si lo desea."],
["No machaque demasiado los garbanzos. Queremos textura, así que deje algunos trozos enteros. Prepare la ensalada con anticipación, pero espere para armar el sándwich hasta el día en que planee comerlo para evitar que el pan se ponga empapado. Pruebe esta ensalada de garbanzos sin el pan, si lo prefiere. Sírvala sobre una cama de lechuga romana, iceberg o espinacas baby. También puede prepararla como wrap. O úntela sobre galletas saladas o apio. La información nutricional incluye un tercio de la ensalada de garbanzos, sin pan ni coberturas. Las distintas marcas de pan en rebanadas varían mucho, así que siempre revise la etiqueta nutricional. La ensalada de garbanzos sobrante se conserva refrigerada hasta por 4 días."],[]))
X.append(r(9738619,"Cupcakes veganos red velvet más saludables [sin colorante alimentario]","¡Cupcakes veganos red velvet saludables y con los que se antojará! Sin colorante alimentario, hechos con ingredientes naturales y ¡INCREÍBLEMENTE sabrosos!","12 cupcakes","1 porción",
[("Ingredientes húmedos","1 taza de puré de betabel (remolacha), de aprox. 2 betabeles pequeños/2 tazas en cubos/o use enlatado"),("Ingredientes húmedos","10 cucharadas (½ taza + 2 cucharadas) de leche de soya"),("Ingredientes húmedos","1 cucharadita de vinagre de manzana"),("Ingredientes húmedos","½ taza de jarabe de arce"),("Ingredientes húmedos","2 cucharaditas de extracto puro de vainilla"),("Ingredientes secos","240 gramos de harina integral para repostería, aprox. 2 tazas"),("Ingredientes secos","3 cucharadas de cacao en polvo crudo sin azúcar"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","½ cucharadita de bicarbonato de sodio"),("Para el glaseado vegano estilo queso crema","1 bloque de 340 gramos (12 onzas) de tofu extra firme, use sin transgénicos si es posible"),("Para el glaseado vegano estilo queso crema","¼ de taza de nueces de la India (anacardos) crudas"),("Para el glaseado vegano estilo queso crema","5-6 cucharadas de jarabe de arce"),("Para el glaseado vegano estilo queso crema","2 cucharaditas de extracto puro de vainilla")],
["Precaliente el horno a 350°F/176°C y forre un molde para magdalenas con capacillos para cupcakes.","Si usa betabeles frescos, pélelos y córtelos en cubos. Luego lleve a ebullición a fuego medio-alto y cocine hasta que estén muy blandos y un tenedor los atraviese fácilmente, aprox. 20-25 minutos. (También puede usar betabeles enlatados para una preparación más rápida.) Una vez cocidos, macháquelos para obtener 1 taza de puré. Asegúrese de no usar más de 1 taza de puré de betabel.","Mientras tanto, agregue la leche de soya y el vinagre de manzana a un tazón pequeño y reserve durante 5 minutos para que espese y se cuaje. Este es su suero de mantequilla (buttermilk) vegano.","Agregue el puré de betabel, su suero de mantequilla vegano, la vainilla y el jarabe de arce a un tazón grande para mezclar. Revuelva hasta combinar. Si los betabeles no se cocinaron lo suficiente y la masa se ve con grumos, coloque todos los líquidos en la licuadora y procese hasta que quede suave. Luego devuélvalos al tazón.","Ahora agregue todos los ingredientes secos al mismo tazón y mezcle hasta combinar, sin mezclar de más.","Luego divida la masa entre los 12 moldes para cupcakes y hornee hasta que un palillo insertado en el centro salga limpio, aprox. 18-20 minutos.","¡Deje que las magdalenas reposen sobre una rejilla hasta que estén completamente frías antes de cubrirlas con el glaseado!",("Para el glaseado","Agregue todos los ingredientes a la licuadora y procese hasta que quede completamente suave, empezando con 5 cucharadas de jarabe de arce. Pruebe y agregue otra cucharada de jarabe si lo prefiere más dulce. Tenga en cuenta que no debe exagerar, o el glaseado quedará demasiado líquido para decorar con manga pastelera."),("Para el glaseado","Si el glaseado se calienta mientras licúa (esto puede ocurrir en licuadoras potentes), pásela a un tazón y colóquelo en el congelador durante 30 minutos antes de decorar sus cupcakes con la manga pastelera.")],
["Pese la harina para obtener los resultados más exactos. Le recomiendo mucho que no se base en las medidas en tazas al hornear. Si no tiene una báscula de cocina, puede poner la harina con una cuchara en la taza medidora y usar un cuchillo para nivelar el exceso, con resultados similares. ¡No la tome con la taza directamente de la bolsa! Si usa betabeles enlatados, ¡asegúrese de que no estén en escabeche! Use betabeles enlatados solo en agua, sin vinagre ni aceite, ya que eso alteraría el sabor. Use polvo para hornear fresco y activo. El polvo para hornear que lleva abierto en su despensa más de 6 meses puede empezar a perder su efectividad. Si no tiene una licuadora potente, remoje las nueces de la India en agua caliente durante 30 minutos antes de licuar el glaseado. Esto ayudará a que se hinchen y ablanden, haciéndolas más fáciles de licuar hasta obtener un glaseado suave. Asegúrese de presionar muy bien el tofu para eliminar el exceso de líquido y evitar que el glaseado quede demasiado líquido. Si el glaseado se calienta mientras licúa (esto puede ocurrir en licuadoras potentes), pásela a un tazón y colóquelo en el congelador durante 30 minutos antes de decorar los cupcakes con la manga pastelera. Deje enfriar los cupcakes en el molde por lo menos 10 minutos antes de manipularlos. Luego páselos a una rejilla para que se enfríen por completo ANTES de cubrirlos con el glaseado. Saben mejor los días 1-2, pero puede guardar las sobras en el refrigerador hasta por 4 días. Guárdelos en un recipiente sellado para conservar la humedad. O congélelos en un recipiente hermético apto para congelador hasta por 3 meses."],[]))
X.append(r(9740076,"Bolitas energéticas de mantequilla de maní","Estas bolitas energéticas de mantequilla de maní son un desayuno FANTÁSTICO para preparar con anticipación y empezar el día con algo saciante y satisfactorio.","22 bolitas","1 porción",
["1 lata de 15 onzas de frijoles blancos (alubias), aprox. 1.5 tazas","½ taza de mantequilla de maní, de la que contiene SOLO maní","½ taza de jarabe de arce","¾ de taza de avena en hojuelas","¾-1 taza de harina de almendra",("Opcional","¼ de taza de chispas de chocolate oscuro")],
["Escurra y enjuague la lata de frijoles y agréguelos al procesador de alimentos, junto con todos los demás ingredientes, empezando con 3/4 de taza de harina de almendra. Procese hasta que esté completamente combinado, raspando los lados según sea necesario.","Revise la consistencia de la mezcla; si le parece demasiado blanda o pegajosa para formar bolitas, agregue la 1/4 de taza restante de harina de almendra y pulse para combinar.","Use una cuchara pequeña para galletas o una cucharada para tomar porciones de la mezcla y formar bolitas de media pulgada. Colóquelas sobre una hoja de papel pergamino o un plato y repita con el resto de la mezcla de mantequilla de maní. Debería obtener alrededor de 22 bolitas energéticas."],
["Use mantequilla de maní natural cuyo único ingrediente sea el maní, sin azúcar ni sal añadidas.","Si su mantequilla de nueces es muy líquida, puede necesitar más harina de almendra para que la consistencia sea lo bastante firme para formar bolitas.","Forme las bolitas con las manos húmedas para evitar que la mezcla se pegue a las manos y los dedos.","Guarde las bolitas a temperatura ambiente de 2 a 3 días, en el refrigerador hasta por 5 días, o en un recipiente hermético en el congelador hasta por 3 meses."],[]))
X.append(r(9740595,"Receta de guacamole de 4 ingredientes","¡Una receta de guacamole de 4 ingredientes que puede preparar en 5 minutos o menos!","6 porciones","1 porción",
["3 aguacates maduros","2 cucharadas de salsa extra con trozos, me gusta la mediana o la picante","1 cucharada de jugo de limón, aprox. ½ limón recién exprimido","½ cucharadita de sal marina o al gusto","¼ de cucharadita de ajo en polvo, opcional"],
["Corte los aguacates por la mitad y retire los huesos. Luego saque la pulpa con una cuchara y colóquela en un tazón para mezclar. Con un tenedor grande o un machacador de papas, macháquelos sin machacar demasiado. Deje algunos trozos más grandes si le gusta más textura.","Agregue los demás ingredientes y revuelva para combinar.","Sirva con tacos veganos, nachos, burritos o totopos."],
["Use aguacates muy maduros para obtener el mejor sabor y textura.","No machaque demasiado los aguacates. Macháquelos a mano, no con licuadora ni procesador de alimentos, o quedarán demasiado suaves. Creo que el mejor guacamole tiene algunos trozos más grandes intactos.","Use su salsa favorita, la que tenga más sabor. Como no usamos tomates ni jalapeños frescos, quiere asegurarse de que su salsa sea de buena calidad. Me gusta la salsa mediana con trozos, pero use el nivel de picante que prefiera.","Ajuste los sabores a su gusto. Como con cualquier receta, ajuste el condimento a su preferencia. Los aguacates varían de tamaño, así que pruebe el guacamole antes de servir y agregue más sal o jugo de limón si es necesario.","Guarde las sobras en el refrigerador con envoltura plástica directamente sobre el guacamole para evitar que se oscurezca, durante 2-3 días."],[]))
X.append(r(9741235,"El mejor sándwich vegano de queso a la plancha","El mejor sándwich vegano de queso a la plancha, con \"queso\" elástico y rodajas de tomate y aguacate. Es delicioso, reconfortante y está listo en un santiamén.","3 sándwiches","1 porción",
["1/4 de taza de nueces de la India (anacardos) crudas","1 cucharada de almidón de tapioca","1 cucharada de levadura nutricional","1.5 cucharaditas de vinagre de manzana","1/4 de cucharadita de sal marina","1/2 taza de agua","6 rebanadas de pan integral en rebanadas (o el de su elección)","1-2 cucharadas de mantequilla vegana (opcional)","rodajas de tomate (opcional)","rodajas de aguacate (opcional)"],
["Hierva agua en una tetera o en la estufa y remoje las nueces de la India en el agua caliente durante 20 minutos. Luego escúrralas.","Luego tueste el pan en una tostadora y unte la mantequilla en cada rebanada, si la usa. O puede engrasar una sartén de hierro fundido con mantequilla y tostar el pan en la estufa. Reserve.","Agregue TODOS los ingredientes del queso, incluidas las nueces de la India ya escurridas, a la licuadora y procese hasta que quede suave.","Luego vierta la mezcla líquida en una sartén en la estufa y cocine a fuego lento hasta que espese y esté elástica, revolviendo con frecuencia. Pasará de líquido a una textura derretida y como de queso en aprox. 2-4 minutos.","Divida el queso entre los 3 sándwiches y agregue las rodajas de tomate y aguacate, si los usa. Sirva de inmediato mientras el queso esté tibio. Si se enfría más rápido de lo que puede prepararlo, devuelva los sándwiches armados a la sartén para recalentar por ambos lados."],[],[]))
X.append(r(9741995,"Cazuela vegana de arroz y brócoli con \"queso\" [sin aceite]","La cazuela vegana de arroz y brócoli es cremosa, con sabor a \"queso\" y rebosante de delicioso sabor. El arroz y los floretes de brócoli se cubren con una rica y aterciopelada salsa de queso vegana y se hornean hasta quedar burbujeantes.","4 porciones","1 porción",
["2 tazas de arroz integral cocido sobrante; si no tiene arroz cocido, comience a cocinarlo mientras prepara los demás ingredientes","3.5-4 tazas de floretes de brócoli, aprox. 1 cabeza pequeña de brócoli cortada en floretes del tamaño de un bocado",("Para el queso","¾ de taza de nueces de la India (anacardos) crudas"),("Para el queso","⅓ de taza de almidón de tapioca, también conocido como harina de tapioca"),("Para el queso","¼ de taza de levadura nutricional"),("Para el queso","½ taza de leche de nuez de la India (anacardo) o de almendras sin azúcar"),("Para el queso","1.5 tazas de agua"),("Para el queso","1.5 cucharaditas de vinagre de manzana"),("Para el queso","1 cucharadita de sal marina o al gusto"),("Para el queso","½ cucharadita de cebolla en polvo"),("Para el queso","½ cucharadita de ajo en polvo"),("Para el queso","1 cucharadita de chile en polvo, para dar sabor, no picante"),("Para el queso","¼ de cucharadita de cúrcuma")],
["Precaliente el horno a 400 grados F.","Agregue todos los ingredientes del queso a una licuadora de alta velocidad y procese hasta que quede suave. Quedará muy líquido.","Coloque el arroz cocido y los floretes de brócoli en un recipiente apto para horno que mida 8x12, o similar. Luego vierta la salsa de queso sobre el arroz y el brócoli, y mezcle bien para cubrir y distribuir de manera uniforme.","Hornee de 20 a 25 minutos, mezclando a la mitad del tiempo. Agregue un poco más de leche si la salsa de queso se espesa demasiado.","Opcional pero recomendado: Gratine la cazuela de 2 a 3 minutos para dorar la parte superior."],
["Si no tiene brócoli fresco, puede sustituirlo por congelado. Para una versión sin nueces, puede sustituir las nueces de la India por semillas de girasol, con resultados similares. Me parece que las nueces de la India dan un resultado un poco más rico aquí, así que a menos que no pueda comerlas, no recomiendo hacer el cambio. Si no tiene una licuadora de alta velocidad, remoje las nueces de la India en agua hirviendo y luego escúrralas, antes de agregarlas a la licuadora. Esto ayudará a que se descompongan hasta obtener una consistencia más suave. Como alternativa, puede colar la salsa de queso una vez licuada, usando una bolsa para leche de nueces. Una vez licuada, su salsa de queso estará muy líquida, pero espesará en el horno al cocinarse. Si su queso se espesa demasiado en el horno, agregue un chorrito o dos más de leche y mezcle bien para que vuelva a quedar cremoso. Este plato se disfruta mejor caliente, recién salido del horno, ya que la salsa de queso espesará al comenzar a enfriarse. Las sobras se conservan refrigeradas de 2 a 3 días. Recaliente las sobras para devolver la salsa de queso a un estado más cremoso."],[]))
X.append(r(9743063,"Galletas de proteína de 3 ingredientes","Galletas de proteína de 3 ingredientes, masticables y deliciosas, sin necesidad de proteína en polvo.","6 galletas","1 porción",
["⅔ de taza de plátano (banana) machacado, aprox. 2 plátanos medianos","100 gramos de mantequilla de maní en polvo, aprox. 1 taza","100 gramos de harina de almendra, aprox. 1 taza"],
["Precaliente el horno a 350℉/176℃ y forre una bandeja para hornear con papel pergamino.","Machaque muy bien los plátanos en un tazón para mezclar hasta que estén muy blandos y líquidos. Luego agregue el polvo de mantequilla de maní (PB) y la harina de almendra y revuelva hasta combinar.","Coloque montoncitos de la mezcla con una cuchara sobre la bandeja para hornear preparada para formar 6 galletas grandes (u 8-10 más pequeñas). Luego dé forma a las galletas y use el reverso de una cuchara o un tenedor para presionarlas y crear un patrón entrecruzado si lo desea.","Luego hornee de 11 a 12 minutos hasta que estén firmes al tacto."],
["Pese la harina/el polvo para obtener los resultados más exactos. Tomarlos con la taza directamente de la bolsa a menudo hace que se use demasiada harina por compactarla en la taza medidora.","Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y nivele la parte superior con un cuchillo, pero no la tome directamente de la bolsa.","Si la masa parece seca (esto variará según lo maduros que estén los plátanos y cómo se midieron los polvos), agregue 1-2 cucharaditas de leche sin lácteos o agua. (¡Solo si es necesario!)"],[]))
X.append(r(9747909,"Sopa fría vegana de pera","¡Una sopa fría vegana de pera dulce y salada, increíblemente sabrosa, con solo 8 ingredientes!","3 porciones","1 porción",
["2 cucharadas de mantequilla vegana","½ taza de cebolla amarilla picada en cubos","2 dientes de ajo picados finamente","2 libras de peras maduras, aprox. 8 peras medianas, cortadas en cuartos","2 cucharadas de jugo de limón","½ cucharadita de canela","1 cucharada de jarabe de arce, opcional","½ taza de leche de soya o de almendras/nuez de la India (anacardo)",("Decoración opcional","crema de nuez de la India (anacardo)")],
["Programe el horno en función de asar (broil) a temperatura alta, con la rejilla superior a unas 6 pulgadas del quemador superior.","Derrita la mantequilla en una sartén de hierro fundido u otra sartén apta para horno a fuego medio. Luego agregue la cebolla y el ajo y saltee hasta que estén translúcidos y ligeramente caramelizados, aprox. 5 minutos.","Apague el fuego y agregue las peras en cuartos, el jugo de limón, la canela y el jarabe de arce, y revuelva para cubrir. Luego coloque la sartén en el horno y áselas con el asador unos 7-10 minutos, hasta que las peras estén ligeramente doradas.","Retire del horno y pase con cuidado la sopa a una licuadora. Agregue la leche y haga puré hasta que quede suave y cremoso. Pruebe y agregue un poco de sal y pimienta si es necesario.","Vierta la sopa de pera en tazones y disfrute tibia, O déjela reposar a temperatura ambiente durante unos 20-30 minutos antes de disfrutarla."],
["Disfrute esta sopa de pera tibia O fría. Sabe fantástica de ambas maneras, pero los sabores parecen mezclarse muy bien una vez que se enfría ligeramente a temperatura ambiente. Las sobras se conservan refrigeradas en un recipiente sellado de 3 a 4 días, o congeladas en un recipiente hermético apto para congelador hasta por 3 meses."],[]))
X.append(r(9751449,"Papas fritas de camote congeladas en freidora de aire","¡Papas fritas de camote (batata) en freidora de aire, doradas, crujientes y deliciosas! No podría ser más sencillo de preparar para la guarnición perfecta de sus hamburguesas y más.","3 porciones","1 porción",
["1 libra de papas fritas de camote (batata) congeladas, aprox. 4 tazas",("Opcional","mayonesa con sriracha para mojar"),("Opcional","perejil o romero fresco"),("Opcional","sal + pimienta al gusto")],
["Pese o mida las papas fritas y colóquelas en la canasta. No es necesario que estén en una sola capa, pero distribúyalas de manera uniforme.","Cocine en la freidora de aire a 400 grados F de 15 a 20 minutos, o hasta alcanzar la textura crujiente deseada. Mezcle a la mitad del tiempo y revíselas con frecuencia hacia el final de la cocción."],
["Revise las papas fritas con frecuencia hacia el final de la cocción para evitar que se quemen. Como todas las freidoras funcionan de manera diferente, algunas pueden cocinar más rápido que otras."],[]))
X.append(r(9753801,"Plátanos machos dulces + picantes en freidora de aire","Los plátanos machos dulces y picantes en freidora de aire son una deliciosa guarnición o entrada. Sabrosos, con toques de dulzor, acidez y picante para una combinación de sabores fabulosa, y listos en menos de 15 minutos, de principio a fin.","2 porciones","1 porción",
["1 plátano macho grande maduro, amarillo opaco con manchas negras","1 cucharadita de sriracha o la salsa picante de su elección","1 cucharadita de jarabe de arce","1 cucharadita de tamari o salsa de soya","1 cucharadita de jugo de limón","1 cucharadita de pimentón ahumado o dulce"],
[("Para cocinar en freidora de aire","Precaliente la freidora a 370 grados F y rocíe el fondo de la canasta con aceite en aerosol para cocinar. Luego combine todos los ingredientes del adobo en un tazón pequeño y mezcle bien."),("Para cocinar en freidora de aire","Pele y corte en rodajas los plátanos machos (de aprox. 1/4\" de grosor) y colóquelos en el tazón con el adobo. Mezcle suavemente para cubrir cada rodaja de manera uniforme."),("Para cocinar en freidora de aire","Distribuya los plátanos machos en una sola capa con bastante espacio entre ellos y cocine en la freidora de aire de 4 a 5 minutos, luego voltee y cocine otros 4-5 minutos hasta que los bordes estén dorados y crujientes."),("Para hornear","Precaliente el horno a 425 grados F en modo de hornear con convección y forre una bandeja grande para hornear con papel pergamino. Luego combine todos los ingredientes del adobo en un tazón pequeño y mezcle bien."),("Para hornear","Pele y corte en rodajas los plátanos machos (de aprox. 1/4\" de grosor) y colóquelos en el tazón con el adobo. Mezcle suavemente para cubrir cada rodaja de manera uniforme."),("Para hornear","Distribuya los plátanos machos en una sola capa sobre la bandeja y hornee durante 15 minutos. Luego voltee y hornee de 5 a 10 minutos más, hasta que los bordes estén dorados y crujientes.")],
["Elija plátanos machos maduros con la cáscara amarilla opaca y muchas manchas negras. Asegúrese de distribuir las rodajas de plátano macho en una sola capa con bastante espacio entre ellas, sin importar el método de cocción que elija. Esto dará como resultado la mejor textura y bordes crujientes, y evitará que las piezas se peguen entre sí. Manipule las rodajas con cuidado al voltearlas para no aplastarlas. Estos plátanos machos saben mejor recién hechos, pero puede guardar las sobras en un recipiente sellado en el refrigerador de 3 a 4 días."],[]))
X.append(r(9758847,"Pasta al pesto con verduras","Una pasta al pesto con verduras fresca y deliciosa, saciante e increíblemente sabrosa.","4 porciones","1 porción",
[("Para la pasta","1 calabacín (zucchini) cortado en cuartos y en rodajas gruesas"),("Para la pasta","1 pinta de tomates uva"),("Para la pasta","1 pimiento rojo picado en cubos grandes"),("Para la pasta","1 pimiento amarillo picado en cubos grandes"),("Para la pasta","½ libra de rigatoni o la pasta de su elección"),("Para el pesto","2 tazas de hojas de albahaca fresca, compactadas"),("Para el pesto","3 dientes de ajo pelados"),("Para el pesto","2 cucharadas de jugo de limón, aprox. la mitad de un limón grande"),("Para el pesto","¼ de taza del agua de la pasta reservada"),("Para el pesto","sal + pimienta al gusto"),("Para decorar/servir","queso parmesano vegano"),("Para decorar/servir","albahaca fresca"),("Para decorar/servir","hojuelas de chile rojo")],
["Precaliente el horno a 425℉/218℃ en modo de asado con convección y forre una bandeja grande para hornear con papel pergamino.","Distribuya las verduras picadas sobre la bandeja y áselas durante 15 minutos, o hasta que los bordes estén dorados.","Mientras tanto, lleve a ebullición una olla grande con agua generosamente salada y cocine la pasta según las instrucciones del paquete para pasta 'al dente'. Escurra (PERO RESERVE 1/4-1/2 taza del agua), devuélvala a la olla y reserve.","Mientras tanto, prepare el pesto. Agregue la albahaca, el ajo y el jugo de limón al procesador de alimentos y procese hasta que esté finamente picado. Luego, con el procesador en marcha, agregue lentamente 1/4 de taza (o más si es necesario) del agua con almidón reservada hasta alcanzar la consistencia deseada. Pruebe la sal y la pimienta y ajuste según sea necesario.","Agregue el pesto y las verduras asadas a la olla con la pasta escurrida, mezcle bien y sirva."],
["Ponga sal al agua de cocción. Asegúrese de agregar suficiente sal a la olla de agua para obtener la mejor textura y sabor. Aquí hay una guía práctica para ayudarle a salar el agua perfectamente cada vez.","Cocine hasta lograr la textura 'al dente'. ¡No la cocine de más! Al dente significa que la pasta sigue firme una vez cocida, lo que da la textura ideal en cada bocado. Para asegurarse de que no se cocine de más, empiece a probarla unos minutos antes de que el paquete indique que estará lista. Debe estar tierna, pero aún firme.","Las sobras se conservan refrigeradas de 3 a 4 días."],[]))
X.append(r(9759865,"Sloppy Joes de lentejas en Instant Pot (con instrucciones para la estufa)","Los sustanciosos y nutritivos sloppy joes de lentejas en Instant Pot están llenos de sabor, son saciantes y deliciosos.","8 porciones","1 porción",
["1 cebolla amarilla picada en cubos","1 pimiento rojo picado en cubos","4 tazas de caldo de verduras bajo en sodio *vea las notas","1 taza de lentejas marrones o verdes","1 taza de lentejas rojas partidas","2 cucharadas de pasta de tomate","2 cucharadas de tamari o salsa de soya si no evita el gluten","1 cucharadita de comino","1 cucharadita de pimentón ahumado","1 taza de salsa de tomate o puré de tomate *vea las notas",("Opcional","panes de hamburguesa veganos u otros panes de su elección"),("Opcional","ensalada de col (coleslaw)"),("Opcional","pepinillos y/o cebollas encurtidas")],
[("Instrucciones para Instant Pot","Seleccione la función de saltear en su Instant Pot y agregue la cebolla y los pimientos con una o dos cucharadas de agua y saltee de 2 a 3 minutos hasta que se ablanden. Luego agregue todos los demás ingredientes, cierre la tapa y gire la válvula a la posición de sellado. Programe a alta presión durante 6 minutos. (Tardará de 10 a 15 minutos en acumular presión antes de comenzar la cuenta regresiva.) Cuando termine el temporizador, libere el vapor rápidamente con la válvula."),("Instrucciones para Instant Pot","Sirva con panes y coberturas o disfrute como sopa."),("Instrucciones para la estufa","En una cacerola grande a fuego medio, agregue la cebolla y los pimientos con una o dos cucharadas de agua y saltee de 2 a 3 minutos hasta que se ablanden"),("Instrucciones para la estufa","Agregue todos los demás ingredientes a la olla y lleve a ebullición a fuego alto. Una vez que hierva, baje el fuego a medio-bajo y cocine a fuego lento de 25 a 30 minutos, o hasta que las lentejas estén cocidas y los líquidos estén casi absorbidos."),("Instrucciones para la estufa","Sirva con panes y coberturas o disfrute como sopa.")],
["*Conviértalo en sopa: Para preparar sopa vegana de sloppy joe, agregue una taza adicional de salsa de tomate y dos tazas adicionales de caldo de verduras a su olla. Es decir, use 6 tazas de caldo y 2 tazas de salsa. No agregue sal. Omitir la sal en la receta no fue un descuido. Si usa caldo y tamari o salsa de soya, probablemente no necesitará sal adicional. Una vez cocido, pruebe y agregue más sal si es necesario. Use lentejas rojas PARTIDAS, no lentejas rojas enteras. Las lentejas partidas absorben más caldo y salsa y hacen que el plato quede espeso para que el sándwich se sostenga bien. Si no tiene lentejas rojas partidas, los guisantes partidos amarillos o verdes también cumplen bien esta función. Si no tiene lentejas ni guisantes partidos, use más lentejas verdes o marrones con resultados similares. Ajuste el condimento: No tenga miedo de condimentarlos más para realzar el sabor. Los mantengo ligeramente condimentados para que sean aptos para niños, pero si desea picante, agregue un poco de pimienta de cayena o uno o dos chorritos de salsa picante. Para una versión sin soya: Omita el tamari y use aminos de coco O omítalo y agregue un poco de sal, al gusto. Para más nutrientes, agregue más verduras picadas como apio, papa en cubos, champiñones, guisantes y/o zanahorias. Las sobras se conservan refrigeradas de 3 a 4 días o congeladas en un recipiente hermético apto para congelador hasta por 3 meses."],[]))
X.append(r(9761419,"Hummus de jalapeño","Una de mis formas favoritas de preparar hummus, un poco picante.","6 personas","1 porción",
["1 lata de garbanzos (15 onzas)","1/4 de taza de tahini","1-2 jalapeños (según qué tan picante lo desee)","1 limón (exprimido)","1/4 de taza de agua (o un poco más si lo desea más líquido)"],
["Escurra y enjuague los garbanzos, y retire los tallos de los jalapeños.","Luego ponga todo en un procesador de alimentos o licuadora y licúe hasta que quede tan suave como lo desee. Puede agregar más agua si lo desea más líquido, o puede usar aceite de oliva, pero a mí me gusta mantenerlo bajo en grasa, así que usamos agua.","Puede decorar el hummus con más jalapeños picados, u omitir esa parte.","Sirva con verduras crudas, pan o lo que prefiera."],[],[]))
X.append(r(9762136,"Ensalada de betabel y brócoli asados","Una ensalada de betabel (remolacha) y brócoli asados tan llena de sabor que le pedirán que la prepare una y otra vez.","4 porciones","1 porción",
[("Para la ensalada","3 tazas de floretes de brócoli en trozos del tamaño de un bocado"),("Para la ensalada","3 tazas de betabel (remolacha) en cubos, en trozos del tamaño de un bocado"),("Para la ensalada","1.5 tazas de garbanzos, cocidos o enlatados (aprox. 1 lata de 15 onzas)"),("Para la ensalada","3 cucharadas de arándanos rojos secos"),("Para el aderezo","3 cucharadas de tahini"),("Para el aderezo","2 cucharadas de vinagre de manzana"),("Para el aderezo","2 cucharadas de jarabe de arce"),("Para el aderezo","½ cucharadita de ajo en polvo"),("Para el aderezo","½ cucharadita de jengibre en polvo"),("Para el aderezo","sal + pimienta al gusto")],
["Precaliente el horno a 425℉/218℃ y forre una bandeja grande para hornear con papel pergamino.","Corte el brócoli en floretes pequeños y pele y corte los betabeles en cubos pequeños de media pulgada. Distribuya las verduras picadas y los garbanzos en una sola capa sobre una bandeja para hornear y espolvoree con sal y pimienta negra. Hornee de 25 a 30 minutos, hasta que los betabeles estén tiernos al pincharlos con un tenedor. Retire la bandeja del horno y deje que las verduras se enfríen un poco.","Mientras tanto, agregue los ingredientes del aderezo a un tazón pequeño, batiendo para combinar bien.","Agregue los betabeles asados, el brócoli, los garbanzos, los arándanos rojos secos y el aderezo a un tazón mediano/grande y revuelva hasta que todo esté cubierto de manera uniforme. Disfrute su ensalada de betabel y brócoli recién hecha para obtener las mejores texturas."],
["Corte los betabeles pequeños para que se cocinen más rápido. O si tiene dificultad para cortarlos lo bastante pequeños, hornéelos primero 15 minutos y luego agregue el brócoli y los garbanzos a la bandeja.","Pruebe y ajuste el aderezo para ensalada a su gusto antes de mezclar."],[]))
save(8,X)
